  border-radius: 8px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  transition: background 120ms ease, border-color 120ms ease, transform 60ms ease;
}
.btn:hover {
  background: #232a32;
  border-color: #4a5462;
}
.btn:active {
  transform: translateY(1px);
}
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn-danger {
  background: var(--danger);
  color: var(--danger-fg);
  border-color: transparent;
}
.btn-danger:hover {
  background: var(--danger-hover);
}

.btn .icon {
  width: 16px;
  height: 16px;
  flex: none;
}

/* Dialog */
dialog.confirm-dialog {
  border: 1px solid var(--border-strong);
  background: var(--surface);
  color: var(--text);
  border-radius: 14px;
  padding: 0;
  max-width: min(440px, calc(100% - 32px));
  width: 100%;
  box-shadow: var(--shadow);
  overflow: hidden;
}
dialog.confirm-dialog::backdrop {
  background: rgba(3, 6, 10, 0.65);
  backdrop-filter: blur(2px);
}

.dialog-body {
  padding: 24px 24px 8px;
}

.dialog-body h2 {
  margin: 0 0 8px;
  font-size: 1.125rem;
  font-weight: 600;
}
.dialog-body p {
  margin: 0;
  color: var(--text-muted);
}

.dialog-footer {
  padding: 16px 24px 20px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

@media (max-width: 420px) {
  .dialog-footer { flex-direction: column-reverse; }
  .dialog-footer .btn { width: 100%; justify-content: center; }
}

.status-region {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .btn { transition: none; }
}

@media (forced-colors: active) {
  .btn, dialog.confirm-dialog { border-color: CanvasText; }
  .btn-danger { background: Mark; color: MarkText; }
}
